fn independent(database:&SqliteDatabase,offset:i64,edit:Option<&str>)->SqliteDatabase{
 use std::{io::Write,process::{Command,Stdio}};let bytes=export_sqlite_database(database,Default::default(),&mut |_|true).unwrap();let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));const edit=process.argv.at(-1),offset=Number(process.argv.at(-2));d.exec('PRAGMA foreign_keys=OFF');if(edit){d.exec('PRAGMA ignore_check_constraints=ON');d.exec(edit)}else{d.run('UPDATE semio_text_run SET id=id+?',[offset]);d.run('UPDATE semio_text_mark SET id=id+?,run_id=run_id+?',[offset,offset]);d.exec('PRAGMA foreign_keys=ON');if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('original text SQLite relations')}await Bun.write(Bun.stdout,d.serialize());d.close();"#;let mut child=Command::new("bun").args(["-e",script,"--",&offset.to_string(),edit.unwrap_or("")]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));import_sqlite_database(&output.stdout,Default::default(),&mut |_|true).unwrap()
}
