fn semio_text_original_receiving_all_fields_empty_groups_nonlink_hrefs_and_signed_ids(){
 let c=contract();let coordinate=dialect();for case in c["cases"].as_array().unwrap(){let input=source(&case["snapshot"]);let pointer=input.schema.as_ptr();let expected=database(&input);let(projected,b,r)=decode(grant(),0,0,|sql,owner|input.to_sqlite_database_receiving(sql,owner));assert_eq!(projected.as_ref().unwrap(),&expected);let(a,z)=close(projected.unwrap());assert_eq!(b+a,r+z);
  for offset in c["signedOffsets"].as_array().unwrap(){let database=independent(&expected,offset.as_i64().unwrap(),None);let pointer=database.tables.as_ptr();let(restored,b,r)=encode(grant(),0,0,|sql,owner|SemioTextSnapshot::from_sqlite_database_receiving(&database,sql,owner));assert_eq!(restored.as_ref().unwrap(),&input);let(a,z)=close(restored.unwrap());assert_eq!(b+a,r+z);
   for(result,b,r)in [decode(grant(),0,0,|sql,owner|input.validate_sqlite_snapshot_subset_decoding(&coordinate,&database,sql,owner).map(|_|()).map_err(|error|error.cause)),encode(grant(),0,0,|sql,owner|input.validate_sqlite_snapshot_subset_encoding(&coordinate,&database,sql,owner).map(|_|()).map_err(|error|error.cause))]{result.unwrap();assert_eq!(b,r)}assert_eq!(pointer,database.tables.as_ptr());
  }assert_eq!(pointer,input.schema.as_ptr());
 }
}
